import{z as A,x as p,o as e,c as B,q as o,j as r,D as l,d as t,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"光瞳测量","description":"","frontmatter":{"title":"光瞳测量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pupil-metrology.md","filePath":"litho/pupil-metrology.md","lastUpdated":1791413859000}'),d={name:"litho/pupil-metrology.md"};function h(C,a,m,u,D,S){const i=p("Mermaid");return e(),B("div",null,[a[2]||(a[2]=o('<h1 id="光瞳测量" tabindex="-1">光瞳测量 <a class="header-anchor" href="#光瞳测量" aria-label="Permalink to &quot;光瞳测量&quot;">​</a></h1><div class="epigraph"><p>配方写的环形 σ 是意图；光瞳计看到的才是进入物镜的角谱。SMO 没有计量就是开环。</p><footer>—— 对照源计量 / pupil metrology；[FlexRay](/litho/flexray-pupil)、[SMO](/litho/smo)</footer></div><p><a href="/litho/illumination-uniformity-slit">上一课</a>测场均匀。缺口是角向：部分相干与离轴照明活在光瞳。本课钉光瞳测量，不重推 Hopkins TCC。位置轴与角度轴正交：上一课管狭缝方向强度均不均，本课管每个方向上 σ 内外环、偶极张角与极平衡——两套账互不替代。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可编程光瞳会漂：镜子、积尘、通道失效。无计量时，偶极张角和 σ 外环只存在于配方文件。OPE 与 SRAF 对光瞳形状敏感，漂移表现为系统 CD 偏差，被误判成 OPC 模型过期。</p><p><span class="marginnote">术语翻译：所谓「角谱」，就是把照进物镜的光按传播方向拆开逐份记账——光瞳上每一个位置对应一组角度，看光瞳等于看「光都朝哪些方向去了」。把它想象成把和弦拆成一个个单音来检查，哪根弦松了一眼就能看出。</span></p><p>展开：可编程照明是数千面微镜拼出的软件图像，实现侧的漂移有三类——微镜倾角标定缓漂、个别镜单元卡死或失效、上游光学积尘把孔径边缘磨钝；偏振态再叠一层（<a href="/litho/illuminator-polarization">照明偏振</a>）。落到成像上是几个可预算的症状：偶极两极失衡给出横竖线 CD 的系统偏差；σ 内外环漂移搬动 <a href="/litho/iso-dense-bias">iso-dense bias</a> 与 Bossung 斜率（<a href="/litho/bossung-curve">Bossung 曲线</a>）；辅助特征阈值随角谱漂，<a href="/litho/sraf-assist">SRAF</a> 过印或欠印，热点被误报到 OPC 头上——模型被无端重标定，真正的源漂移还留在台上。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在照明光瞳共轭面用阵列传感器或扫描针孔重建 \\(I(\\rho,\\phi)\\)。指标：σ、环宽、偶极平衡、椭圆度、与目标图的 RMSE。进 SMO 闭环：测到的源才是计算光刻用的源，而不是 CAD 里的理想源。</p><p>工程流程：机台内置光瞳填充传感器，按照明设置逐一取图；校准循环里把每个常用设置的 σ 内外环、极平衡、椭圆度与目标图 RMSE 记档，超限即触发微镜阵列再标定或上游除尘。计量结果直接写进模型库：<a href="/litho/smo">SMO</a> 在实测源上优化，OPC 按机台实测源标定；做 <a href="/litho/model-residual-analysis">模型残差分析</a>时先排除源漂移再怀疑模型，能省掉大半冤枉重标定。测量口径要统一：光瞳计报「离开照明」的角谱，「到达晶圆」还要过物镜与掩模三维，两套口径不能并表。</p>',10)),(e(),r(n,null,{default:l(()=>[s(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E9%85%8D%E6%96%B9%E5%85%89%E7%9E%B3%22%5D%20--%3E%20ILL%5B%22%E7%85%A7%E6%98%8E%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20ILL%20--%3E%20MEAS%5B%22%E5%85%89%E7%9E%B3%E8%AE%A1%22%5D%0A%20%20MEAS%20--%3E%20SMO%5B%22OPC%20%2F%20SMO%20%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"掩模 3D 与物镜 NA 限制哪些角能进胶。光瞳计应报「离开照明」还是「到达晶圆」——两者差一层物镜与偏振。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"TCC 由源与光瞳共同决定。源计量误差线性进部分相干核。场均匀计量不替代光瞳计量。",-1)),a[6]||(a[6]=E("p",null,"写透一点：TCC 是源点加权的瞳函数自相关，源强度的小误差以 \\(\\delta\\mathrm{TCC}\\approx(\\partial\\mathrm{TCC}/\\partial S)\\,\\delta S\\) 的形式线性进空中像——这正是源误差不需要重推理论、只需要计量与替换的原因。源误差还要分类：形状误差（σ、环宽、张角、极平衡）改成像对比与方向性偏置，能量误差归剂量闭环管，两路别混。极平衡偏差在成像上是有方向的偏置，正是它让横竖线在同一场里反向漂，是最容易被误认成镜片像差的源侧症状。",-1)),(e(),r(n,null,{default:l(()=>[s(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%AE%9E%E6%B5%8B%E6%BA%90%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20CLS%7B%22%E5%85%88%E5%88%86%E7%B1%BB%22%7D%0A%20%20CLS%20--%3E%20SHP%5B%22%E5%BD%A2%E7%8A%B6%E8%AF%AF%E5%B7%AE%EF%BC%9A%CF%83%20%E7%8E%AF%E5%AE%BD%20%E5%BC%A0%E8%A7%92%20%E6%9E%81%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20CLS%20--%3E%20ENE%5B%22%E8%83%BD%E9%87%8F%E8%AF%AF%E5%B7%AE%EF%BC%9A%E6%80%BB%E5%BC%BA%E5%BA%A6%22%5D%0A%20%20SHP%20--%3E%20TCC%5B%22%CE%B4TCC%20%E7%BA%BF%E6%80%A7%E8%BF%9B%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A%20%20ENE%20--%3E%20DOSE%5B%22%E5%89%82%E9%87%8F%E9%97%AD%E7%8E%AF%E5%90%B8%E6%94%B6%22%5D%0A%20%20TCC%20--%3E%20SYM%5B%22%E6%96%B9%E5%90%91%E6%80%A7%E5%81%8F%E7%BD%AE%20%2F%20%E5%AF%B9%E6%AF%94%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SYM%20--%3E%20CHK%5B%22%E5%85%88%E9%87%8D%E6%A0%87%E5%85%89%E7%9E%B3%E5%86%8D%E8%B0%88%20OPC%20%E9%87%8D%E6%A0%87%E5%AE%9A%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">常见误区：初学者容易以为「源能量漂了百分之几，CD 就跟着漂百分之几」。实际上能量误差被剂量闭环抹平，真正伤 CD 的是形状误差——两极差 5% 的能量就能让横线与竖线往相反方向偏，这种不均匀漂移是任何「整体调剂量」都救不回来的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课剂量传感：标量能量闭环，不是角谱。两者都要，不能互相替代。剂量闭环管总光子数，光瞳计管光子往哪个角度去；一边失控表现为 CD 整体漂，一边失控表现为方向性偏置与热点。</p><p><span class="marginnote">直觉类比：剂量闭环像总水管上的水表，只管流了多少水；光瞳计像装在每个喷头上的角度仪，管水往哪个方向喷。水表读数正常不代表喷头没歪——只看剂量传感器，方向性的漂移永远测不到。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光瞳计把照明从开环配方变成可校准角谱。</li><li>SMO / OPE 必须吃实测源。</li><li>源误差经 TCC 线性进像，先查源再怪模型。</li><li>出处：源计量通识；SMO 与 FlexRay 课。</li></ul>',6))])}const F=A(d,[["render",h]]);export{T as __pageData,F as default};
